struct EquityOptionBuilder {
  typedef EquityOption Table;
  ::flatbuffers::FlatBufferBuilder &fbb_;
  ::flatbuffers::uoffset_t start_;
  void add_trade_id(::flatbuffers::Offset<::flatbuffers::String> trade_id) {
    fbb_.AddOffset(EquityOption::VT_TRADE_ID, trade_id);
  }
  void add_underlying_id(::flatbuffers::Offset<::flatbuffers::String> underlying_id) {
    fbb_.AddOffset(EquityOption::VT_UNDERLYING_ID, underlying_id);
  }
  void add_quantity(double quantity) {
    fbb_.AddElement<double>(EquityOption::VT_QUANTITY, quantity, 1.0);
  }
  void add_settlement(quantra::enums::EquitySettlementType settlement) {
    fbb_.AddElement<int8_t>(EquityOption::VT_SETTLEMENT, static_cast<int8_t>(settlement), 0);
  }
  void add_payoff_type(quantra::EquityPayoff payoff_type) {
    fbb_.AddElement<uint8_t>(EquityOption::VT_PAYOFF_TYPE, static_cast<uint8_t>(payoff_type), 0);
  }
  void add_payoff(::flatbuffers::Offset<void> payoff) {
    fbb_.AddOffset(EquityOption::VT_PAYOFF, payoff);
  }
  void add_exercise_type(quantra::EquityExercise exercise_type) {
    fbb_.AddElement<uint8_t>(EquityOption::VT_EXERCISE_TYPE, static_cast<uint8_t>(exercise_type), 0);
  }
  void add_exercise(::flatbuffers::Offset<void> exercise) {
    fbb_.AddOffset(EquityOption::VT_EXERCISE, exercise);
  }
  void add_barrier(::flatbuffers::Offset<quantra::EquityBarrierFeature> barrier) {
    fbb_.AddOffset(EquityOption::VT_BARRIER, barrier);
  }
  explicit EquityOptionBuilder(::flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  ::flatbuffers::Offset<EquityOption> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = ::flatbuffers::Offset<EquityOption>(end);
    fbb_.Required(o, EquityOption::VT_TRADE_ID);
    fbb_.Required(o, EquityOption::VT_UNDERLYING_ID);
    return o;
  }
};

inline ::flatbuffers::Offset<EquityOption> CreateEquityOption(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> trade_id = 0,
    ::flatbuffers::Offset<::flatbuffers::String> underlying_id = 0,
    double quantity = 1.0,
    quantra::enums::EquitySettlementType settlement = quantra::enums::EquitySettlementType_Physical,
    quantra::EquityPayoff payoff_type = quantra::EquityPayoff_NONE,
    ::flatbuffers::Offset<void> payoff = 0,
    quantra::EquityExercise exercise_type = quantra::EquityExercise_NONE,
    ::flatbuffers::Offset<void> exercise = 0,
    ::flatbuffers::Offset<quantra::EquityBarrierFeature> barrier = 0) {
  EquityOptionBuilder builder_(_fbb);
  builder_.add_quantity(quantity);
  builder_.add_barrier(barrier);
  builder_.add_exercise(exercise);
  builder_.add_payoff(payoff);
  builder_.add_underlying_id(underlying_id);
  builder_.add_trade_id(trade_id);
  builder_.add_exercise_type(exercise_type);
  builder_.add_payoff_type(payoff_type);
  builder_.add_settlement(settlement);
  return builder_.Finish();
}

